#!/usr/bin/env python3
"""Reproduce the 27 kernel-checked integer blocks for RS1962 equation (3.9).

Python selects endpoints only. Lean recomputes each count using Mathlib's
binary primality instance and checks every bound with `decide +kernel`.
"""
from __future__ import annotations

import argparse
from math import isqrt
from pathlib import Path

ROOT = Path(__file__).resolve().parent
HEADER = """/-
Copyright (c) 2026 IEANTN contributors. All rights reserved.
Released under Apache 2.0 license as described in the file LICENSE.
Authors: IEANTN contributors
-/
-- Generated by generate.py; do not edit. Counts are rechecked by the Lean kernel.
"""


def generated() -> dict[str, str]:
    counts = [0] * 2048
    for n in range(2, 2048):
        prime = all(n % d != 0 for d in range(2, isqrt(n) + 1))
        counts[n] = counts[n - 1] + int(prime)
    blocks: list[tuple[int, int]] = []
    a = 2
    while a < 1024:
        b = a
        while b + 1 < 1024:
            candidate = b + 1
            if (counts[2 * candidate + 1] - counts[a]) * (candidate + 1).bit_length() > 2 * a:
                break
            b = candidate
        blocks.append((a, b))
        a = b + 1
    assert len(blocks) == 27
    outputs: dict[str, str] = {}
    for shard in range(3):
        group = blocks[shard * 9:(shard + 1) * 9]
        previous = "Finite.Base" if shard == 0 else f"Finite.Data{shard - 1:02}"
        text = HEADER + f"import {previous}\n\nset_option maxRecDepth 10000\nset_option maxHeartbeats 0\n\nnamespace RS39\n\n"
        for i, (left, right) in enumerate(group):
            index = shard * 9 + i
            text += f"theorem check_{index:02} :\n    (fastCount {2 * right + 1} - fastCount {left}) * (Nat.log 2 {right + 1}+1) ≤ {2 * left} := by\n  decide +kernel\n\n"
        text += f"theorem finite_{shard:02} (n : ℕ) (ha : {group[0][0]} ≤ n) (hb : n ≤ {group[-1][1]}) :\n    (Nat.primeCounting (2*n+1) - Nat.primeCounting n) * (Nat.log 2 (n+1)+1) ≤ 2*n := by\n"
        for i, (_, right) in enumerate(group[:-1]):
            index = shard * 9 + i
            text += f"  by_cases h{index} : n ≤ {right}\n  · exact range_bound (by omega) h{index} check_{index:02}\n"
        index = shard * 9 + len(group) - 1
        text += f"  exact range_bound (by omega) hb check_{index:02}\n\nend RS39\n"
        outputs[f"Finite/Data{shard:02}.lean"] = text
    outputs["Finite/All.lean"] = HEADER + """import Finite.Data02

namespace RS39

theorem finite_certificate : ∀ n ∈ Finset.Icc 2 1023,
    (Nat.primeCounting (2*n+1) - Nat.primeCounting n) * (Nat.log 2 (n+1)+1) ≤ 2*n := by
  intro n hn
  obtain ⟨ha, hb⟩ := Finset.mem_Icc.mp hn
  by_cases h : n ≤ 34
  · exact finite_00 n ha h
  by_cases h' : n ≤ 215
  · exact finite_01 n (by omega) h'
  exact finite_02 n (by omega) hb

end RS39
"""
    return outputs


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    outputs = generated()
    stale = []
    for name, text in outputs.items():
        path = ROOT / name
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != text:
                stale.append(name)
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding="utf-8")
    if stale:
        print("Generated files differ: " + ", ".join(stale))
        return 1
    print(f"{'Checked' if args.check else 'Wrote'} {len(outputs)} generated files (27 blocks).")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
